import json, sys
sys.path.insert(0, '/workspace/project/src'); sys.path.insert(0, '/workspace/tmp')
from eywa.offline import Campaign
from eywa.ast import Array, Bool, Char, Enum, Int, String, Struct, Type
from fuzz_value import ktest

def node_of(t):
    t = Type.inner(t)
    if isinstance(t, Bool): return ('bool', None)
    if isinstance(t, Char): return ('char', None)
    if isinstance(t, Int): return ('int', t.bits)
    if isinstance(t, Enum): return ('enum', t.values)
    if isinstance(t, String): return ('string', t.maxsize)
    if isinstance(t, Array): return ('array', node_of(t.element_type), t.size)
    if isinstance(t, Struct): return ('struct', [(f, node_of(ft)) for f, ft in t.fields.items()])
    raise AssertionError(type(t))

E = 32; M = 24
STATES = ["A", "B", "C"]
types = [
    {"name": "N16", "kind": "int", "bits": 16},
    {"name": "N8", "kind": "int", "bits": 8},
    {"name": "B", "kind": "bool"},
    {"name": "S4", "kind": "string", "maxsize": 4},
    {"name": "St", "kind": "enum", "values": STATES},
    {"name": "Pair", "kind": "struct", "fields": [["a", "N8"], ["b", "B"]]},
    {"name": "Arr", "kind": "array", "element": "Pair", "size": 2},
    {"name": "PArr", "kind": "alias", "target": "Arr"},
]
modules = []; pipes = []; calls = []; entries = []
for e in range(E):
    name = "e%d" % e
    entries.append(name)
    modules.append({"name": name,
                    "params": [["n%d" % i, "N16"] for i in range(8)] +
                              [["p", "PArr"], ["s", "S4"], ["state", "St"], ["msg", "S4"]],
                    "result": ["o", "B"],
                    "requires": ["all", "x", ["var", "p"],
                                 ["lt", ["field", ["var", "x"], "a"], ["const", "N8", 200]]]})
    for i in range(M):
        fname = "f%d_%d" % (e, i)
        modules.append({"name": fname, "params": [["q", "N16"]], "result": ["r", "B"],
                        "requires": ["lt", ["var", "q"], ["const", "N16", 60000]]})
        pipes.append({"target": name, "filter": fname, "bind": {"q": "n%d" % (i % 8)}})
    for i in range(M - 1):
        calls.append([name, "f%d_%d" % (e, i)])
machine = {"states": STATES, "initial": "A", "state_param": "state", "message_param": "msg",
           "transitions": [{"from": "A", "to": "B", "command": "ab", "cost": 2, "when": None},
                           {"from": "B", "to": "C", "command": "cd", "cost": 3,
                            "when": ["lt", ["var", "n0"], ["const", "N16", 300]]},
                           {"from": "A", "to": "C", "command": "ef", "cost": 6, "when": None}]}
campaign = {"types": types, "modules": modules, "calls": calls, "pipes": pipes,
            "entries": entries, "machine": machine, "runs": []}
camp = Campaign({k: (v if k != 'runs' else []) for k, v in campaign.items()})
camp.certificate()
by_path = {}
for plan in camp.plans:
    for tag, path, width in plan.slots:
        by_path[(plan.entry, tuple(path))] = tag
result_tag = {plan.entry: [t for t, p, w in plan.slots if p == ['o']][0] for plan in camp.plans}
flag_tag = {plan.entry: plan.flag for plan in camp.plans}
shapes = {plan.entry: [(name, node_of(kind)) for name, kind in plan.module.params]
          for plan in camp.plans}
runs = []
for r in range(2048):
    e = "e%d" % (r % E)
    values = {"n%d" % i: 100 + (r % 200) for i in range(8)}
    values['p'] = [{'a': r % 250, 'b': True}, {'a': 1, 'b': False}]
    values['s'] = 'ab'
    values['state'] = STATES[r % 3]
    values['msg'] = 'zz'
    objects = []
    def emit(path, value, node):
        kind = node[0]
        if kind in ('bool', 'char', 'int', 'enum'):
            if kind == 'bool': data = b'\x01' if value else b'\x00'
            elif kind == 'int': data = value.to_bytes(node[1], 'little')
            elif kind == 'enum': data = node[1].index(value).to_bytes(4, 'little')
            else: data = ord(value).to_bytes(1, 'little')
            objects.append((by_path[(e, tuple(path))], data))
        elif kind == 'string':
            for i, c in enumerate(value.ljust(node[1], '\x00')[:node[1]]):
                objects.append((by_path[(e, tuple(path + [i]))], ord(c).to_bytes(1, 'little')))
        elif kind == 'array':
            for i, item in enumerate(value):
                emit(path + [i], item, node[1])
        elif kind == 'struct':
            for f, sub in node[1]:
                emit(path + [f], value[f], sub)
    for name, shape in shapes[e]:
        emit([name], values[name], shape)
    objects.append((result_tag[e], b'\x01'))
    objects.append((flag_tag[e], b'\x00'))
    runs.append({"entry": e, "ktest": ktest(objects)})
campaign['runs'] = runs
sys.stdout.write(json.dumps(campaign))
